custom_css:
/* Mystic Glass Theme - 温暖舒适版 */

/* 整体透明背景 */
body {
    background: transparent !important;
}

#chat {
    background: transparent !important;
}

/* 磨砂玻璃效果消息气泡 */
.mes {
    background: rgba(45, 40, 35, 0.5) !important;
    border-radius: 20px !important;
    backdrop-filter: blur(12px) saturate(180%) !important;
    margin: 10px 4px !important;
    padding: 16px !important;
    border: 1px solid rgba(255, 240, 220, 0.12);
    box-shadow: 0 8px 32px rgba(0, 0, 0, 0.3) !important;
}

/* 用户消息 - 暖橙色调 */
.mes.user {
    background: rgba(75, 55, 40, 0.55) !important;
    border: 1px solid rgba(255, 180, 120, 0.25);
}

/* AI消息 - 暖青色调 */
.mes[isbot="true"] {
    background: rgba(40, 60, 65, 0.5) !important;
    border: 1px solid rgba(150, 200, 200, 0.25);
}

/* 头像 - 柔和圆角矩形 */
.avatar {
    border-radius: 18px !important;
    border: 3px solid rgba(255, 240, 220, 0.35) !important;
    box-shadow: 0 4px 20px rgba(255, 200, 150, 0.35), inset 0 0 20px rgba(255, 240, 220, 0.1) !important;
    transition: all 0.4s cubic-bezier(0.4, 0, 0.2, 1) !important;
    overflow: hidden;
}

.avatar:hover {
    border-color: rgba(255, 240, 220, 0.6) !important;
    box-shadow: 0 6px 30px rgba(255, 200, 150, 0.5), inset 0 0 30px rgba(255, 240, 220, 0.15) !important;
    transform: scale(1.08) rotate(1deg) !important;
}

/* 头像图片 */
.avatar-img {
    width: 85px !important;
    height: 85px !important;
    object-fit: cover !important;
    filter: brightness(1.05) contrast(1.05);
}

/* 对话中的头像 */
.mes .avatar {
    width: 75px !important;
    height: 75px !important;
}

/* 头像外发光动画 */
@keyframes softGlow {
    0%, 100% { box-shadow: 0 4px 20px rgba(255, 200, 150, 0.35); }
    50% { box-shadow: 0 4px 25px rgba(255, 200, 150, 0.5); }
}

.avatar {
    animation: softGlow 4s ease-in-out infinite;
}

/* 文字优化 */
.mes_text,
.mes .mes_text {
    text-shadow: 0 2px 4px rgba(0, 0, 0, 0.6), 0 0 20px rgba(255, 240, 220, 0.1) !important;
    line-height: 1.8 !important;
}

/* 斜体文字 */
.mes_text em {
    color: rgba(255, 220, 180, 1) !important;
}

/* 引用文字 */
.blockquote {
    border-left: 3px solid rgba(255, 200, 150, 0.6) !important;
    background: rgba(255, 200, 150, 0.08) !important;
    padding: 12px 16px !important;
    border-radius: 8px !important;
}

/* 滚动条 - 暖色系 */
::-webkit-scrollbar {
    width: 12px !important;
}

::-webkit-scrollbar-track {
    background: rgba(30, 25, 20, 0.3) !important;
    border-radius: 6px;
}

::-webkit-scrollbar-thumb {
    background: linear-gradient(180deg, rgba(255, 200, 150, 0.4), rgba(255, 180, 140, 0.4)) !important;
    border-radius: 6px;
    border: 1px solid rgba(255, 220, 180, 0.2);
}

::-webkit-scrollbar-thumb:hover {
    background: linear-gradient(180deg, rgba(255, 200, 150, 0.7), rgba(255, 180, 140, 0.7)) !important;
}

/* 输入框 - 磨砂玻璃 */
#form_prompt {
    background: rgba(35, 30, 25, 0.65) !important;
    border: 1px solid rgba(255, 240, 220, 0.18) !important;
    border-radius: 16px !important;
    backdrop-filter: blur(15px) saturate(180%) !important;
    box-shadow: inset 0 2px 10px rgba(0, 0, 0, 0.3) !important;
}

/* 发送按钮 - 渐变暖色 */
#dialogue_send {
    background: linear-gradient(135deg, rgba(255, 180, 120, 0.7), rgba(255, 200, 150, 0.7)) !important;
    border: none !important;
    border-radius: 14px !important;
    box-shadow: 0 4px 15px rgba(255, 180, 120, 0.4) !important;
    transition: all 0.3s ease !important;
}

#dialogue_send:hover {
    background: linear-gradient(135deg, rgba(255, 190, 130, 0.9), rgba(255, 210, 160, 0.9)) !important;
    transform: translateY(-3px);
    box-shadow: 0 6px 25px rgba(255, 180, 120, 0.6) !important;
}

/* 侧边栏 */
#right-nav-panel,
#left-nav-panel {
    background: rgba(30, 25, 20, 0.75) !important;
    backdrop-filter: blur(20px) saturate(180%) !important;
    border: 1px solid rgba(255, 240, 220, 0.1);
}

/* 顶部栏 */
#top-bar-holder {
    background: rgba(30, 25, 20, 0.85) !important;
    backdrop-filter: blur(20px) saturate(180%) !important;
    border-bottom: 1px solid rgba(255, 240, 220, 0.15);
}

/* 角色列表项 */
.character-select {
    background: rgba(45, 40, 35, 0.4) !important;
    border: 1px solid rgba(255, 240, 220, 0.1) !important;
    border-radius: 12px !important;
}

.character-select:hover {
    background: rgba(55, 50, 45, 0.5) !important;
    border-color: rgba(255, 200, 150, 0.3) !important;
}
